func TestSanity_NewWithBuffer(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	logger, closer := logging.New(context.Background(), logging.Options{
		Output: &buf,
		Level:  slog.LevelDebug,
	})
	t.Cleanup(func() { _ = closer() })
	ctx := logging.WithLogger(context.Background(), logger)

	logging.Info(ctx, "hello")

	if !strings.Contains(buf.String(), "\"msg\":\"hello\"") {
		t.Errorf("expected hello in output, got: %s", buf.String())
	}
}

func TestSanity_LoggerFromContextFallback(t *testing.T) {
	t.Parallel()
	if logging.LoggerFromContext(context.Background()) == nil {
		t.Fatal("expected non-nil fallback")
	}
	if logging.LoggerFromContext(nil) == nil { //nolint:staticcheck // testing nil-safety
		t.Fatal("expected non-nil fallback for nil ctx")
	}
}

func TestSanity_ResolveLevel(t *testing.T) {
	t.Parallel()
	tests := []struct {
		env, settings string
		want          slog.Level
	}{
		{"", "", slog.LevelInfo},
		{"DEBUG", "", slog.LevelDebug},
		{"", "WARN", slog.LevelWarn},
		{"DEBUG", "WARN", slog.LevelDebug},
		{"bogus", "", slog.LevelInfo},
	}
	for _, tt := range tests {
		got := logging.ResolveLevel(tt.env, tt.settings)
		if got != tt.want {
			t.Errorf("ResolveLevel(%q, %q) = %v, want %v", tt.env, tt.settings, got, tt.want)
