// log is the internal logging function that routes a record to either the
// ctx-carried logger or, during migration, the package-level logger set by
// Init.
//
// The read lock is held across the legacy l.Log so Init/Close cannot close
// logBufWriter mid-write while a record is in flight. The ctx-logger path
// does not need the lock because the logger value in ctx is immutable for
// the lifetime of the request and the file closer fires only after
// ExecuteContext returns.
func log(ctx context.Context, level slog.Level, msg string, attrs ...any) {
	mu.RLock()
	defer mu.RUnlock()

	// Migration bridge: when Init() set the global logger, route through
	// the legacy path so per-command Init/Close still observe writes to
	// the configured log file. Once all callers move to WithLogger, the
	// global stays nil and this branch is unreachable — task 10 deletes it.
	if logger != nil {
		legacyLog(ctx, logger, currentSessionID, level, msg, attrs...)
		return
	}

	LoggerFromContext(ctx).Log(ctx, level, msg, attrs...)
}

// legacyLog reproduces the pre-refactor attr extraction so that callers still
// invoking Init() observe the same record shape during migration.
func legacyLog(ctx context.Context, l *slog.Logger, globalSessionID string, level slog.Level, msg string, attrs ...any) {
	var allAttrs []any
	if globalSessionID != "" {
		allAttrs = append(allAttrs, slog.String("session_id", globalSessionID))
	}
	for _, a := range attrsFromContext(ctx, globalSessionID) {
		allAttrs = append(allAttrs, a)
	}
	allAttrs = append(allAttrs, attrs...)
	l.Log(nil, level, msg, allAttrs...) //nolint:staticcheck // nil context is intentional - attrs already extracted
}

