// Close closes the log file if one is open.
// Flushes any buffered data before closing.
// Safe to call multiple times.
//
// After Close, the package-level logger is cleared so any subsequent log()
// calls fall through to the ctx-carried logger. This avoids tests leaking a
// stale global between runs while the legacy path is being phased out.
func Close() {
	mu.Lock()
	defer mu.Unlock()

	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}
	logger = nil
	currentSessionID = ""
}

