func TestEnrichmentChain_ComposesAllAttrs(t *testing.T) {
	t.Parallel()
	ctx, buf := withTestLogger(t)
	ctx = WithSession(ctx, "session-1")
	ctx = WithComponent(ctx, testComponent)
	ctx = WithToolCall(ctx, "tool-1")
	ctx = WithAgent(ctx, testAgent)
	Info(ctx, "all-attrs")

